package studio.solocamera;

import android.app.*;
import android.content.Intent;
import android.os.*;
import android.view.*;
import android.widget.*;
import androidx.media3.common.C;
import androidx.media3.common.audio.AudioProcessor;
import java.nio.*;
import java.lang.reflect.*;
import java.util.*;

/** Isolated model/DSP tests plus real activity navigation; no user project is edited. */
@androidx.annotation.OptIn(markerClass=androidx.media3.common.util.UnstableApi.class)
final class CreatorToolsChecks {
    private static void check(boolean ok,String label){if(!ok)throw new AssertionError(label);}
    private static Object field(Object object,String name)throws Exception{Field f=object.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(object);}
    private static void invoke(Object object,String name)throws Exception{Method m=object.getClass().getDeclaredMethod(name);m.setAccessible(true);m.invoke(object);}
    private static void command(MainActivity activity,String action,Object value)throws Exception{Method m=MainActivity.class.getDeclaredMethod("command",String.class,Object.class);m.setAccessible(true);m.invoke(activity,action,value);}
    private static void ui(Instrumentation host,Throwing action){Throwable[] error={null};host.runOnMainSync(()->{try{action.run();}catch(Throwable e){error[0]=e;}});if(error[0]!=null)throw new RuntimeException(error[0]);}
    private interface Throwing{void run()throws Exception;}
    private static org.json.JSONObject state(Instrumentation host,MainActivity a){org.json.JSONObject[] value={null};ui(host,()->value[0]=(org.json.JSONObject)field(a,"state"));return value[0];}
    private static void waitState(Instrumentation host,MainActivity a,String key,boolean expected)throws Exception{long end=SystemClock.elapsedRealtime()+15000;while(SystemClock.elapsedRealtime()<end){if(state(host,a).optBoolean(key)==expected)return;Thread.sleep(100);}throw new AssertionError("Camera state timeout "+key+" "+state(host,a));}
    private static View find(View v,String text){if(text.contentEquals(v.getContentDescription()==null?"":v.getContentDescription()))return v;if(v instanceof TextView&&((TextView)v).getText().toString().contains(text))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View found=find(((ViewGroup)v).getChildAt(i),text);if(found!=null)return found;}return null;}
    static void run(Instrumentation host,Bundle result)throws Exception{
        EditorProject project=new EditorProject();EditorProject.Clip source=new EditorProject.Clip("video:test","QA",6000);source.audioSyncMs=150;source.markers.put(new org.json.JSONObject().put("at",3000).put("kind","good"));project.clips.add(source);
        EditorProject.Audio voice=new EditorProject.Audio();voice.uri="test";voice.name="Narration";voice.duration=4000;voice.start=1000;voice.end=3000;voice.at=2000;voice.narration=true;voice.activity=new float[]{0,1,0,0};project.audios.add(voice);project.duckStrength=.8;project.duckFadeMs=200;
        CreatorDucking envelope=new CreatorDucking(project);check(envelope.gain(1000)==1,"duck before narration");check(Math.abs(envelope.gain(2500)-.2)<.00001,"duck active narration");check(Math.abs(envelope.gain(1900)-.6)<.00001,"duck attack");check(envelope.gain(3500)==1,"duck silence restoration");
        EditorProject restored=EditorProject.from(project.json().toString());check(restored.clips.get(0).audioSyncMs==150&&restored.clips.get(0).markers.length()==1,"sync/markers persistence");check(restored.audios.get(0).narration&&restored.audios.get(0).activity[1]==1&&restored.duckStrength==.8,"duck persistence");source.copy().markers.put(new org.json.JSONObject());check(source.markers.length()==1,"marker copies must be independent");
        for(int correction:new int[]{-20,0,20})for(int encoding:new int[]{C.ENCODING_PCM_16BIT,C.ENCODING_PCM_FLOAT})for(int channels:new int[]{1,2}){
            SyncAudioProcessor sync=new SyncAudioProcessor(correction);int sampleBytes=encoding==C.ENCODING_PCM_FLOAT?4:2;sync.configure(new AudioProcessor.AudioFormat(1000,channels,encoding));sync.flush();ByteBuffer input=ByteBuffer.allocateDirect(100*channels*sampleBytes).order(ByteOrder.nativeOrder());for(int i=0;i<100;i++)for(int c=0;c<channels;c++)if(sampleBytes==4)input.putFloat(i/100f);else input.putShort((short)(i*100));input.flip();sync.queueInput(input);ByteBuffer output=sync.getOutput().order(ByteOrder.nativeOrder());ArrayList<Float> samples=new ArrayList<>();while(output.remaining()>=sampleBytes)samples.add(sampleBytes==4?output.getFloat():output.getShort()/10000f);sync.queueEndOfStream();output=sync.getOutput().order(ByteOrder.nativeOrder());while(output.remaining()>=sampleBytes)samples.add(sampleBytes==4?output.getFloat():output.getShort()/10000f);check(samples.size()==100*channels,"sync changed sample count: offset="+correction+" encoding="+encoding+" channels="+channels+" samples="+samples.size());check(Math.abs(samples.get(30*channels)-(30+correction)/100f)<.0001,"sync direction / stereo alignment");sync.reset();
        }
        int[] pixels=new int[64];Arrays.fill(pixels,0xffffffff);CreatorSignal.overlay(pixels,8,8,true,false,235);check(Arrays.stream(pixels).anyMatch(v->v!=0),"zebra missing");Arrays.fill(pixels,0xff303030);CreatorSignal.overlay(pixels,8,8,false,true,235);check(Arrays.stream(pixels).allMatch(v->v==0),"peaking on flat image");
        DuckingAudioProcessor duck=new DuckingAudioProcessor(project,2200);duck.configure(new AudioProcessor.AudioFormat(1000,1,C.ENCODING_PCM_16BIT));duck.flush();ByteBuffer wave=ByteBuffer.allocateDirect(20).order(ByteOrder.nativeOrder());for(int i=0;i<10;i++)wave.putShort((short)10000);wave.flip();duck.queueInput(wave);check(Math.abs(duck.getOutput().order(ByteOrder.nativeOrder()).getShort()-2000)<=1,"duck PCM gain");duck.reset();
        final Throwable[] error={null};EditorActivity activity=(EditorActivity)host.startActivitySync(new Intent(host.getTargetContext(),EditorActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final String[] draft={null};
        host.runOnMainSync(()->{try{invoke(activity,"startNewProject");EditorProject empty=(EditorProject)field(activity,"project");draft[0]=empty.id;check(empty.clips.isEmpty()&&empty.captions.isEmpty(),"new project not empty");check(find(activity.getWindow().getDecorView(),"Your story starts here")!=null,"empty workspace missing");invoke(activity,"showLibrary");check(find(activity.getWindow().getDecorView(),"Start a new project")!=null,"new project action missing");invoke(activity,"showEditor");invoke(activity,"creatorTools");}catch(Throwable e){error[0]=e;}});if(error[0]!=null)throw new RuntimeException(error[0]);
        host.waitForIdleSync();host.runOnMainSync(()->activity.finish());host.waitForIdleSync();if(draft[0]!=null)new java.io.File(EditorProject.directory(host.getTargetContext()),draft[0]+".json").delete();
        result.putString("checks","PASS new draft/workspace/library navigation; marker/sync/duck persistence and independent marker copies; 12 PCM sync cases (advance/delay, mono/stereo, integer/float, preserved sample count); narration trim/silence/fades; duck export processor; zebra and peaking flat-field checks");
    }
    static void capture(Instrumentation host,Bundle result)throws Exception{
        MainActivity camera=(MainActivity)host.startActivitySync(new Intent(host.getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
        ui(host,()->{Method role=MainActivity.class.getDeclaredMethod("chooseRole",String.class);role.setAccessible(true);role.invoke(camera,"camera");});waitState(host,camera,"ready",true);org.json.JSONObject saved=new org.json.JSONObject(state(host,camera).toString());
        ui(host,()->command(camera,"shootingPreset",saved));Thread.sleep(800);check(state(host,camera).optInt("videoFps")==saved.optInt("videoFps"),"shooting preset FPS");check(!state(host,camera).optString("notice").startsWith("Rejected"),"shooting preset rejected");
        CreatorRecorder probe=new CreatorRecorder();try{ui(host,()->probe.start(host.getTargetContext(),0));Thread.sleep(800);ui(host,()->{check(!probe.route().isEmpty(),"microphone route missing");java.io.File test=probe.finish();check(test.length()>0,"microphone check empty");test.delete();});}finally{probe.close();}
        ui(host,()->command(camera,"start",null));waitState(host,camera,"recording",true);final android.net.Uri[] take={null};ui(host,()->take[0]=(android.net.Uri)field(field(camera,"camera"),"recordingUri"));Thread.sleep(900);ui(host,()->command(camera,"marker","good"));Thread.sleep(500);ui(host,()->command(camera,"marker","mistake"));Thread.sleep(900);ui(host,()->command(camera,"stop",null));waitState(host,camera,"recording",false);Thread.sleep(500);
        org.json.JSONObject notes=CreatorNotes.read(host.getTargetContext(),take[0].toString());check(notes.optJSONArray("markers")!=null&&notes.getJSONArray("markers").length()==2,"recorded markers missing");check(!notes.optString("routeKey").isEmpty(),"microphone route sidecar missing");
        ui(host,camera::finish);host.waitForIdleSync();
        EditorActivity editor=(EditorActivity)host.startActivitySync(new Intent(host.getTargetContext(),EditorActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final EditorProject[] project={null};final String[] draft={null};
        ui(host,()->{invoke(editor,"startNewProject");project[0]=(EditorProject)field(editor,"project");draft[0]=project[0].id;Method read=EditorActivity.class.getDeclaredMethod("readClip",android.net.Uri.class);read.setAccessible(true);EditorProject.Clip clip=(EditorProject.Clip)read.invoke(editor,take[0]);check(clip.markers.length()==2,"markers not imported into editor");project[0].clips.add(clip);project[0].height=720;invoke(editor,"showEditor");invoke(editor,"recordVoiceover");AlertDialog dialog=(AlertDialog)field(editor,"voiceDialog");check(dialog!=null,"voice-over dialog missing");View record=find(dialog.getWindow().getDecorView(),"Record / retry");check(record!=null,"voice-over record control missing");record.performClick();});
        Thread.sleep(4500);ui(host,()->{check(field(editor,"voiceRecorder")!=null,"voice-over did not start");AlertDialog dialog=(AlertDialog)field(editor,"voiceDialog");View stop=find(dialog.getWindow().getDecorView(),"Stop");check(stop!=null,"voice-over stop missing");stop.performClick();View add=find(dialog.getWindow().getDecorView(),"Add voice-over");check(add!=null&&add.isEnabled(),"voice-over take unavailable");add.performClick();});
        long deadline=SystemClock.elapsedRealtime()+15000;while(project[0].audios.isEmpty()&&SystemClock.elapsedRealtime()<deadline)Thread.sleep(100);check(project[0].audios.size()==1&&project[0].audios.get(0).narration&&project[0].audios.get(0).activity.length>0,"voice-over not added as analyzed narration");
        ui(host,()->{invoke(editor,"save");invoke(editor,"syncCalibration");});host.sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);ui(host,()->{invoke(editor,"duckingSettings");});host.sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);ui(host,()->{invoke(editor,"takeMarkers");});host.sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);
        ui(host,()->{project[0].clips.get(0).audioSyncMs=80;EditorProject.Audio voice=project[0].audios.get(0);EditorProject.Audio music=EditorProject.Audio.from(voice.json());music.narration=false;music.duck=true;music.track=1;music.name="QA ducked music";project[0].audios.add(music);invoke(editor,"startExport");});
        deadline=SystemClock.elapsedRealtime()+60000;final boolean[] exporting={true};while(exporting[0]&&SystemClock.elapsedRealtime()<deadline){Thread.sleep(250);ui(host,()->exporting[0]=(Boolean)field(editor,"exporting"));}final Object[] output={null};ui(host,()->output[0]=field(editor,"lastExport"));check(!exporting[0]&&output[0]!=null,"creator tools composite export failed");
        result.putString("capture","PASS actual camera preset application, microphone test, marked camera take, marker import, voice-over record/stop/add/activity analysis, creator dialogs and MP4 export with sync correction + ducking");result.putString("take",take[0].toString());result.putString("export",output[0].toString());ui(host,editor::finish);host.waitForIdleSync();if(draft[0]!=null)new java.io.File(EditorProject.directory(host.getTargetContext()),draft[0]+".json").delete();
    }
}
